algorithms.pseudocode:
ALGORITHM ComputeJoinDistance(t, u, maxDepth)
  Input: Lambda terms t, u; search depth bound
  Output: Minimum k1 + k2 such that t ->^k1 v and u ->^k2 v

  reachT <- {t: 0}, reachU <- {u: 0}
  best <- infinity
  for depth = 0 to maxDepth:
    for v in reachT intersection reachU:
      best <- min(best, reachT[v] + reachU[v])
    Expand reachT, reachU by one step
  return best (or None if infinity)
